        if ((|u_slice.u_s_7N.u.g_mu.u_lep.u.l0_f || |u_slice.u_s_7N.u.g_mu.u_lep.u.l1_f) && !epf0[5]) begin epf0[5] = 1; $fdisplay(fep, "EPF %0d u_s_7N ln 1", cyc); end
        if (((|u_slice.u_s_7N.u.g_mu.u_lep.u.ovf) || u_slice.u_s_7N.u.g_mu.u_lep.u.perr || u_slice.u_s_7N.u.g_mu.u_lep.u.herr) && !epf0[6]) begin epf0[6] = 1; $fdisplay(fep, "EPF %0d u_s_7N io 1", cyc); end
    end
    // ---- endpoint probe u_s_7S
    reg [6:0] epf1 = 0;
    always @(negedge ck) if (rst_n && cyc >= 0 && fep != 0) begin
        if (u_slice.u_s_7S.u.g_mu.u_lep.u.rov) $fdisplay(fep, "EPB %0d u_s_7S %0d %0d %h", cyc, u_slice.u_s_7S.u.g_mu.u_lep.u.bsel, u_slice.u_s_7S.u.g_mu.u_lep.u.roq[3:1], u_slice.u_s_7S.u.g_mu.u_lep.u.fr[1077:1045]);
        if (u_slice.u_s_7S.u.g_mu.u_lep.u.fault && !epf1[0]) begin epf1[0] = 1; $fdisplay(fep, "EPF %0d u_s_7S ep 1", cyc); end
        if (u_slice.u_s_7S.u.g_mu.u_lep.u.terr && !epf1[1]) begin epf1[1] = 1; $fdisplay(fep, "EPF %0d u_s_7S te 1", cyc); end
        if (u_slice.u_s_7S.u.g_mu.mf && !epf1[2]) begin epf1[2] = 1; $fdisplay(fep, "EPF %0d u_s_7S land 1", cyc); end
        if (u_slice.u_s_7S.u.g_mu.u_lep.u.mcol_w && !epf1[3]) begin epf1[3] = 1; $fdisplay(fep, "EPF %0d u_s_7S mcol 1", cyc); end
        if (u_slice.u_s_7S.u.g_mu.u_lep.u.sl_f && !epf1[4]) begin epf1[4] = 1; $fdisplay(fep, "EPF %0d u_s_7S sl 1", cyc); end
        if ((|u_slice.u_s_7S.u.g_mu.u_lep.u.l0_f || |u_slice.u_s_7S.u.g_mu.u_lep.u.l1_f) && !epf1[5]) begin epf1[5] = 1; $fdisplay(fep, "EPF %0d u_s_7S ln 1", cyc); end
        if (((|u_slice.u_s_7S.u.g_mu.u_lep.u.ovf) || u_slice.u_s_7S.u.g_mu.u_lep.u.perr || u_slice.u_s_7S.u.g_mu.u_lep.u.herr) && !epf1[6]) begin epf1[6] = 1; $fdisplay(fep, "EPF %0d u_s_7S io 1", cyc); end
    end
    // ---- TOK-B3 consumer check: probed endpoint beats vs compiled gold (+EPX), in the simulator
    integer fepx = 0, ex_c = 0, ex_i = 0, ex_p = 0, ex_k = 0, ex_h = 0, ep_strict = 1;
    integer n_ep = 0, n_ep_hop = 0, n_ep_bad = 0, n_ep_late = 0;
    reg [32:0] ex_t; reg have_ex = 0;
    reg [1:0] ep_seen; reg [5:0] epm = 0;
    task next_ex;
        begin have_ex = 0;
            if (fepx != 0 && !$feof(fepx)) begin
                rc = $fscanf(fepx, "%d %d %d %d %h %d", ex_c, ex_i, ex_p, ex_k, ex_t, ex_h);
                have_ex = (rc == 6); end
        end
    endtask
    task automatic ep_bad(input integer k, input integer j, input integer why);
        begin n_ep_bad = n_ep_bad + 1; n_bad = n_bad + 1;
            if (n_ep_bad <= 20) $display("TB_DV_SLICE EP_MISMATCH edge %0d probe %0d why %0d (1 missing 2 value 3 unexpected 4 MU fault)", k, j, why);
        end
    endtask
    always @(negedge ck) if (rst_n && cyc >= 0 && fepx != 0) begin
        ep_seen = 0;
        while (have_ex && ex_c < cyc) begin ep_bad(ex_c, ex_i, 1); next_ex(); end
        while (have_ex && ex_c == cyc) begin
            n_ep = n_ep + 1; if (ex_h != 0) n_ep_hop = n_ep_hop + 1;
            case (ex_i)
                0: begin ep_seen[0] = 1;
                    if (!u_slice.u_s_7N.u.g_mu.u_lep.u.rov) ep_bad(cyc, 0, 1);
                    else if (u_slice.u_s_7N.u.g_mu.u_lep.u.bsel != ex_p[0] || u_slice.u_s_7N.u.g_mu.u_lep.u.roq[3:1] != ex_k[2:0] || {1'b0, u_slice.u_s_7N.u.g_mu.u_lep.u.fr[1077:1045]} != ex_t) ep_bad(cyc, 0, 2);
                end
                1: begin ep_seen[1] = 1;
                    if (!u_slice.u_s_7S.u.g_mu.u_lep.u.rov) ep_bad(cyc, 1, 1);
                    else if (u_slice.u_s_7S.u.g_mu.u_lep.u.bsel != ex_p[0] || u_slice.u_s_7S.u.g_mu.u_lep.u.roq[3:1] != ex_k[2:0] || {1'b0, u_slice.u_s_7S.u.g_mu.u_lep.u.fr[1077:1045]} != ex_t) ep_bad(cyc, 1, 2);
                end
                default: ep_bad(cyc, ex_i, 1);
            endcase
            next_ex();
        end
        if (u_slice.u_s_7N.u.g_mu.u_lep.u.rov && !ep_seen[0] && (ep_strict != 0 || |u_slice.u_s_7N.u.g_mu.u_lep.u.fr[1077:1045])) ep_bad(cyc, 0, 3);
        if (u_slice.u_s_7N.u.g_mu.u_lep.u.terr && !epm[0]) begin epm[0] = 1; ep_bad(cyc, 0, 4); end
        if (u_slice.u_s_7N.u.g_mu.mf && !epm[1]) begin epm[1] = 1; ep_bad(cyc, 0, 4); end
        if (u_slice.u_s_7N.u.g_mu.u_lep.u.mcol_w && !epm[2]) begin epm[2] = 1; ep_bad(cyc, 0, 4); end
        if (u_slice.u_s_7S.u.g_mu.u_lep.u.rov && !ep_seen[1] && (ep_strict != 0 || |u_slice.u_s_7S.u.g_mu.u_lep.u.fr[1077:1045])) ep_bad(cyc, 1, 3);
        if (u_slice.u_s_7S.u.g_mu.u_lep.u.terr && !epm[3]) begin epm[3] = 1; ep_bad(cyc, 1, 4); end
        if (u_slice.u_s_7S.u.g_mu.mf && !epm[4]) begin epm[4] = 1; ep_bad(cyc, 1, 4); end
        if (u_slice.u_s_7S.u.g_mu.u_lep.u.mcol_w && !epm[5]) begin epm[5] = 1; ep_bad(cyc, 1, 4); end
    end
    initial begin
        for (k = 0; k < 257; k = k + 1) prev[k] = 0;
        if ($value$plusargs("EP=%s", fn)) fep = $fopen(fn, "w");
        if (!$value$plusargs("NCYC=%d", NCYC)) NCYC = 2000;
        if ($value$plusargs("IN=%s", fn)) begin fin = $fopen(fn, "r"); if (fin == 0) begin $display("TB_DV_SLICE FAIL no IN %s", fn); $finish; end end
        if ($value$plusargs("OUT=%s", fn)) begin fout = $fopen(fn, "r"); if (fout == 0) begin $display("TB_DV_SLICE FAIL no OUT %s", fn); $finish; end end
        if ($value$plusargs("TRACE=%s", fn)) ftr = $fopen(fn, "w");
        if ($value$plusargs("EPX=%s", fn)) begin fepx = $fopen(fn, "r"); if (fepx == 0) begin $display("TB_DV_SLICE FAIL no EPX %s", fn); $finish; end end
        if (!$value$plusargs("EPSTRICT=%d", ep_strict)) ep_strict = 1;
        next_ex();
        next_in(); next_out();
        #0.1 rst_n = 1'b0;
        repeat (NRST) @(posedge ck);
        @(negedge ck);
        $system("date +DV_SLICE_T0=%s.%N");
        rst_n = 1'b1;
        repeat (NCYC) @(posedge ck);
        @(negedge ck);
        $system("date +DV_SLICE_T1=%s.%N");
        if (have_ov) begin $display("TB_DV_SLICE checks left unrun from cycle %0.1f", oc); n_bad = n_bad + 1; end
        if (have_ev) begin $display("TB_DV_SLICE replay events left unapplied from cycle %0.1f", ec); n_bad = n_bad + 1; end
        $display("DV_SLICE cycles=%0d in_events=%0d out_checks=%0d mismatches=%0d fault_cycles=%0d first_fault=%0d", NCYC, n_in, n_chk, n_bad, n_flt, first_flt);
        while (have_ex) begin n_ep_late = n_ep_late + 1; n_bad = n_bad + 1; next_ex(); end
        $display("DV_SLICE_EP consumer_checks=%0d hop_checks=%0d ep_mismatches=%0d past_deadline=%0d strict=%0d", n_ep, n_ep_hop, n_ep_bad, n_ep_late, ep_strict);
        if (n_chk + n_ep == 0) begin $display("TB_DV_SLICE FAIL zero checks (nothing compared)"); n_bad = n_bad + 1; end
        if (ftr != 0) $fclose(ftr);
        if (fep != 0) $fclose(fep);
        if (n_bad == 0 && n_flt == 0) $display("TB_DV_SLICE PASS"); else $display("TB_DV_SLICE FAIL");
        $finish;
    end
endmodule
